-- 17A P3 step (i): dedicated PUBLIC bucket 'public-assets' (images only, 5 MiB, no listing policy) for the public event/profile assets that must leave chat-images before it goes private [APPLY]
-- 17A STORAGE PRIVACY: PROPOSAL ONLY. NOT APPLIED ANYWHERE. GENERATED by db/proposed/17a-storage-privacy/build.mjs (node build.mjs --check fails if this file drifts from its inputs).
-- Apply gate: NO prod SQL and NO Storage API operation without Joe's relayed yes + Sentinel's pass + Atlas's review of the migrations + a backup. Sentinel's inventory/backup files were NOT available to this draft (see README). Order: README.md.
-- Run as postgres, ONE transaction, ON_ERROR_STOP (psql -v ON_ERROR_STOP=1) or a single-call SQL executor; right after BEGIN come SET LOCAL lock_timeout = '5s', the repo-wide pack advisory lock, and SET LOCAL lock_timeout = '5s' again.
-- Run it a second time and it refuses at the guard (state is no longer the captured one) with nothing changed.
-- No object, no row and no data is deleted by this pack.
BEGIN;
-- repo-wide pack key (same as R1 #136 / 12A / 13A): serialises every pack run; transaction-scoped; a second run waits for a running pack to commit or roll back, for at most 5 s:
-- lock_timeout is set BEFORE the lock (so the lock wait itself is bounded) and again right after it (every later lock wait). Expiry = SQLSTATE 55P03, nothing changed.
SET LOCAL lock_timeout = '5s';
SELECT pg_advisory_xact_lock(2979301232487107403);
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

-- 1. DRIFT GUARD: live state must be EXACTLY the captured prod state (policies by name/shape/predicate, bucket settings, ACL classes, prerequisite functions). Anything else aborts with nothing applied.
DO $guard$
DECLARE
  f text[] := ARRAY[]::text[];
  v text;
BEGIN
  IF current_user <> 'postgres' THEN f := f || ('run as postgres; current_user=' || current_user); END IF;
  v := coalesce((SELECT count(*)::text FROM unnest(ARRAY['profile_slug','owner_id']) c WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.profile_owners') AND a.attname = c AND NOT a.attisdropped)), 'ABSENT');
  IF v IS DISTINCT FROM '2' THEN f := f || ('req.profile_owners_cols: expected 2 but live is ' || v); END IF;
  v := coalesce((to_regprocedure('public.is_admin()') IS NOT NULL)::text, 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('req.is_admin_exists: expected true but live is ' || v); END IF;
  v := coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT');
  IF v <> ALL (ARRAY['ABSENT','true']) THEN f := f || ('bucket.public-assets.public: expected ABSENT OR true but live is ' || v); END IF;
  v := coalesce((SELECT coalesce(b.file_size_limit::text,'(null)') FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT');
  IF v <> ALL (ARRAY['ABSENT','5242880']) THEN f := f || ('bucket.public-assets.limit: expected ABSENT OR 5242880 but live is ' || v); END IF;
  v := coalesce((SELECT coalesce((SELECT string_agg(m, ',' ORDER BY m COLLATE "C") FROM unnest(b.allowed_mime_types) m),'(null)') FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT');
  IF v <> ALL (ARRAY['ABSENT','image/avif,image/gif,image/jpeg,image/png,image/webp']) THEN f := f || ('bucket.public-assets.mime: expected ABSENT OR image/avif,image/gif,image/jpeg,image/png,image/webp but live is ' || v); END IF;
  v := coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'public-assets'), 'ABSENT');
  IF v IS DISTINCT FROM '(none)' THEN f := f || ('sel.public-assets: expected (none) but live is ' || v); END IF;
  v := coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('INSERT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'public-assets'), 'ABSENT');
  IF v IS DISTINCT FROM '(none)' THEN f := f || ('ins.public-assets: expected (none) but live is ' || v); END IF;
  IF array_length(f, 1) IS NOT NULL THEN
    RAISE EXCEPTION '17A APPLY-P3a: DRIFT, ABORT, nothing applied. % mismatch(es): %', array_length(f, 1), array_to_string(f, ' ; ');
  END IF;
END
$guard$;

-- 2. INVARIANT SNAPSHOT: everything this pack must NOT change (ACL fingerprints sorted, RLS flags, every other policy, every untouched bucket row, the object name set).
CREATE TEMP TABLE _kil17a_inv ON COMMIT DROP AS
SELECT 'inv.objects_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.buckets_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.buckets'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.objects_rls'::text AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.objects_rows_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(o.bucket_id || '/' || o.name || '/' || coalesce(o.owner_id,''), '|' ORDER BY o.bucket_id, o.name)),'-') FROM storage.objects o), '(null)')::text AS val
UNION ALL SELECT 'inv.other_policies_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(p.policyname || '|' || p.cmd || '|' || array_to_string(p.roles,',') || '|' || p.permissive || '|' || coalesce(p.qual,'') || '|' || coalesce(p.with_check,''), E'\n' ORDER BY p.policyname COLLATE "C")),'-') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname NOT IN ('public_assets_owner_insert','public_assets_owner_admin_read','public_assets_owner_delete')), '(null)')::text AS val
UNION ALL SELECT 'inv.other_buckets_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(b::text, '|' ORDER BY b.id)),'-') FROM storage.buckets b WHERE b.id NOT IN ('public-assets')), '(null)')::text AS val;

-- 3. THE FIX
-- dedicated PUBLIC bucket for the public event flyers / profile images that today live in chat-images. Public READ is by URL only (no SELECT policy for anon, no listing policy).
-- Paths: profiles/<profile slug>/<file>  (writer = an owner of that profile)   |   event-flyers/<uid>/<file>  (writer = that user).  service_role bypasses RLS.
-- NO DELETE of any object or row anywhere in this pack. (The bucket row is created with ON CONFLICT DO NOTHING; the guard accepts an absent bucket or an exact pre-existing copy.)
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('public-assets', 'public-assets', true, 5242880, ARRAY['image/avif','image/gif','image/jpeg','image/png','image/webp']::text[]) ON CONFLICT (id) DO NOTHING;
CREATE POLICY public_assets_owner_insert ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (bucket_id = 'public-assets' AND (
  ((storage.foldername(name))[1] = 'profiles' AND EXISTS (SELECT 1 FROM public.profile_owners po WHERE po.owner_id = (SELECT auth.uid()) AND po.profile_slug = (storage.foldername(name))[2]))
  OR ((storage.foldername(name))[1] = 'event-flyers' AND (storage.foldername(name))[2] = (SELECT auth.uid())::text)));
-- owner-scoped SELECT (own uploads only; needed so a signed-in owner can list/remove their files, e.g. the app's delete-my-account sweep), admins see all. NOT bucket-wide, anon gets none.
CREATE POLICY public_assets_owner_admin_read ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (bucket_id = 'public-assets' AND (owner_id = (SELECT auth.uid())::text
  OR ((storage.foldername(name))[1] = 'profiles' AND EXISTS (SELECT 1 FROM public.profile_owners po WHERE po.owner_id = (SELECT auth.uid()) AND po.profile_slug = (storage.foldername(name))[2])) OR public.is_admin()));
CREATE POLICY public_assets_owner_delete ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (bucket_id = 'public-assets' AND (owner_id = (SELECT auth.uid())::text
  OR ((storage.foldername(name))[1] = 'profiles' AND EXISTS (SELECT 1 FROM public.profile_owners po WHERE po.owner_id = (SELECT auth.uid()) AND po.profile_slug = (storage.foldername(name))[2]))));

-- 4. POST-CHECKS (assert; a failure rolls the whole transaction back)
DO $post$
DECLARE bad text;
BEGIN
  SELECT string_agg(name || ' (expected ' || expected || ', got ' || actual || ')', ' ; ') INTO bad FROM (
WITH a(name, actual) AS (
  SELECT 'req.profile_owners_cols' AS name, coalesce((SELECT count(*)::text FROM unnest(ARRAY['profile_slug','owner_id']) c WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.profile_owners') AND a.attname = c AND NOT a.attisdropped)), 'ABSENT') AS actual
  UNION ALL SELECT 'req.is_admin_exists' AS name, coalesce((to_regprocedure('public.is_admin()') IS NOT NULL)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.public-assets.public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.public-assets.limit' AS name, coalesce((SELECT coalesce(b.file_size_limit::text,'(null)') FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.public-assets.mime' AS name, coalesce((SELECT coalesce((SELECT string_agg(m, ',' ORDER BY m COLLATE "C") FROM unnest(b.allowed_mime_types) m),'(null)') FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.public-assets' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'ins.public-assets' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('INSERT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.public_assets_owner_insert.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'public_assets_owner_insert'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.public_assets_owner_admin_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'public_assets_owner_admin_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.public_assets_owner_delete.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'public_assets_owner_delete'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.no_public_or_anon_policy' AS name, coalesce((SELECT count(*)::text FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'public-assets' AND (p.roles && ARRAY['public','anon']::name[])), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('req.profile_owners_cols', '2', ARRAY['2']::text[]),
  ('req.is_admin_exists', 'true', ARRAY['true']::text[]),
  ('bucket.public-assets.public', 'true', ARRAY['true']::text[]),
  ('bucket.public-assets.limit', '5242880', ARRAY['5242880']::text[]),
  ('bucket.public-assets.mime', 'image/avif,image/gif,image/jpeg,image/png,image/webp', ARRAY['image/avif,image/gif,image/jpeg,image/png,image/webp']::text[]),
  ('sel.public-assets', 'public_assets_owner_admin_read', ARRAY['public_assets_owner_admin_read']::text[]),
  ('ins.public-assets', 'public_assets_owner_insert', ARRAY['public_assets_owner_insert']::text[]),
  ('pol.public_assets_owner_insert.shape', 'INSERT|authenticated|PERMISSIVE', ARRAY['INSERT|authenticated|PERMISSIVE']::text[]),
  ('pol.public_assets_owner_admin_read.shape', 'SELECT|authenticated|PERMISSIVE', ARRAY['SELECT|authenticated|PERMISSIVE']::text[]),
  ('pol.public_assets_owner_delete.shape', 'DELETE|authenticated|PERMISSIVE', ARRAY['DELETE|authenticated|PERMISSIVE']::text[]),
  ('pol.no_public_or_anon_policy', '0', ARRAY['0']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT name, expected, actual, ok FROM r
  ) z WHERE NOT ok;
  IF bad IS NOT NULL THEN RAISE EXCEPTION '17A APPLY-P3a: POST-CHECK FAILED (transaction rolls back): %', bad; END IF;
END
$post$;
DO $invcheck$
DECLARE bad text;
BEGIN
  SELECT string_agg(a.name, ', ') INTO bad FROM _kil17a_inv a JOIN (
    SELECT 'inv.objects_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.buckets_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.buckets'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.objects_rls'::text AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.objects_rows_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(o.bucket_id || '/' || o.name || '/' || coalesce(o.owner_id,''), '|' ORDER BY o.bucket_id, o.name)),'-') FROM storage.objects o), '(null)')::text AS val
    UNION ALL SELECT 'inv.other_policies_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(p.policyname || '|' || p.cmd || '|' || array_to_string(p.roles,',') || '|' || p.permissive || '|' || coalesce(p.qual,'') || '|' || coalesce(p.with_check,''), E'\n' ORDER BY p.policyname COLLATE "C")),'-') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname NOT IN ('public_assets_owner_insert','public_assets_owner_admin_read','public_assets_owner_delete')), '(null)')::text AS val
    UNION ALL SELECT 'inv.other_buckets_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(b::text, '|' ORDER BY b.id)),'-') FROM storage.buckets b WHERE b.id NOT IN ('public-assets')), '(null)')::text AS val
  ) b USING (name) WHERE a.val IS DISTINCT FROM b.val;
  IF bad IS NOT NULL THEN RAISE EXCEPTION '17A APPLY-P3a: INVARIANT CHANGED (the pack must change nothing else; transaction rolls back): %', bad; END IF;
END
$invcheck$;

-- 5. RETAINED OUTPUT: keep this result set with the change record (ok must be true on every row).
WITH a(name, actual) AS (
  SELECT 'req.profile_owners_cols' AS name, coalesce((SELECT count(*)::text FROM unnest(ARRAY['profile_slug','owner_id']) c WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.profile_owners') AND a.attname = c AND NOT a.attisdropped)), 'ABSENT') AS actual
  UNION ALL SELECT 'req.is_admin_exists' AS name, coalesce((to_regprocedure('public.is_admin()') IS NOT NULL)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.public-assets.public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.public-assets.limit' AS name, coalesce((SELECT coalesce(b.file_size_limit::text,'(null)') FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.public-assets.mime' AS name, coalesce((SELECT coalesce((SELECT string_agg(m, ',' ORDER BY m COLLATE "C") FROM unnest(b.allowed_mime_types) m),'(null)') FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.public-assets' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'ins.public-assets' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('INSERT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.public_assets_owner_insert.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'public_assets_owner_insert'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.public_assets_owner_admin_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'public_assets_owner_admin_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.public_assets_owner_delete.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'public_assets_owner_delete'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.no_public_or_anon_policy' AS name, coalesce((SELECT count(*)::text FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'public-assets' AND (p.roles && ARRAY['public','anon']::name[])), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('req.profile_owners_cols', '2', ARRAY['2']::text[]),
  ('req.is_admin_exists', 'true', ARRAY['true']::text[]),
  ('bucket.public-assets.public', 'true', ARRAY['true']::text[]),
  ('bucket.public-assets.limit', '5242880', ARRAY['5242880']::text[]),
  ('bucket.public-assets.mime', 'image/avif,image/gif,image/jpeg,image/png,image/webp', ARRAY['image/avif,image/gif,image/jpeg,image/png,image/webp']::text[]),
  ('sel.public-assets', 'public_assets_owner_admin_read', ARRAY['public_assets_owner_admin_read']::text[]),
  ('ins.public-assets', 'public_assets_owner_insert', ARRAY['public_assets_owner_insert']::text[]),
  ('pol.public_assets_owner_insert.shape', 'INSERT|authenticated|PERMISSIVE', ARRAY['INSERT|authenticated|PERMISSIVE']::text[]),
  ('pol.public_assets_owner_admin_read.shape', 'SELECT|authenticated|PERMISSIVE', ARRAY['SELECT|authenticated|PERMISSIVE']::text[]),
  ('pol.public_assets_owner_delete.shape', 'DELETE|authenticated|PERMISSIVE', ARRAY['DELETE|authenticated|PERMISSIVE']::text[]),
  ('pol.no_public_or_anon_policy', '0', ARRAY['0']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT '000_ALL_OK' AS name, 'POST' AS expected, 'POST' AS actual, bool_and(ok) AS ok FROM r
UNION ALL SELECT name, expected, actual, ok FROM r
